    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False):
        self.fq_name_parts = tuple(fq_name_parts)
        self.is_ambiguous = is_ambiguous
        self.child_is_redirected = child_is_redirected
        self.name_parts = self.fq_name_parts
        self.found = False
        self.redirected = False
        self.is_package = False
        self.py_src = False
        self.path = None
        self.source = None
        self._resolve()

    def candidate_names_joined(self):
        candidates = [self.fq_name_parts]
        if self.is_ambiguous and len(self.fq_name_parts) > self.base_length + 1:
            candidates.append(self.fq_name_parts[:-1])
        return ['.'.join(parts) for parts in candidates]

    def _resolve(self):
        candidates = [tuple(candidate.split('.')) for candidate in self.candidate_names_joined()]
        methods = (self._redirect, self._local) if self.redirect_first else (self._local, self._redirect)
        for method in methods:
            for parts in candidates:
                if method(parts):
                    self.found = True
                    return

    def _redirect(self, parts):
        for length in range(len(parts), self.base_length, -1):
            if length < len(parts) and self.is_ambiguous:
                break
            routed_parts = parts[:length]
            routing = self._routing(routed_parts)
            if not routing:
                continue
            collection_name = self._collection_name()
            full_name = '.'.join(routed_parts)
            deprecation = routing.get('deprecation')
            if deprecation:
                display.deprecated(deprecation.get('warning_text') or '%s has been deprecated' % full_name,
                                   version=deprecation.get('removal_version'), date=deprecation.get('removal_date'),
                                   collection_name=collection_name)
            tombstone = routing.get('tombstone')
            if tombstone:
                message = display.get_deprecation_message(
                    tombstone.get('warning_text') or '%s has been removed.' % full_name,
                    version=tombstone.get('removal_version'), date=tombstone.get('removal_date'),
                    removed=True, collection_name=collection_name)
                raise AnsibleError(message)
            target = routing.get('redirect')
            if not target:
                continue
            if not target.startswith(('ansible_collections.', 'ansible.module_utils.')):
                target = 'ansible_collections.%s.%s.plugins.module_utils.%s' % tuple(target.split('.', 2))
            suffix = parts[length:]
            # A redirected parent must be a package so Python can import its children.
            self.is_package = bool(suffix or self.child_is_redirected)
            self.name_parts = routed_parts
            self.path = '/'.join(routed_parts) + ('/__init__.py' if self.is_package else '.py')
            self.source = to_bytes('import sys\nimport {0} as mod\n{1}sys.modules[{2!r}] = mod\n'.format(
                target, 'import {0}\n'.format('.'.join((target,) + suffix)) if suffix else '', full_name))
            self.py_src = True
            self.redirected = True
            return True
        return False

    def _collection_name(self):
        raise NotImplementedError

    def _routing(self, parts):
        raise NotImplementedError

    def _local(self, parts):
        raise NotImplementedError


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    base_length = 2

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        self.mu_paths = mu_paths if mu_paths is not None else [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)

    def _collection_name(self):
        return 'ansible.builtin'

    def _routing(self, parts):
        metadata = _get_collection_metadata('ansible.builtin')
        key = '.'.join(parts[self.base_length:])
        return metadata.get('plugin_routing', {}).get('module_utils', {}).get(key)

    def _local(self, parts):
        relative = parts[self.base_length:]
        if not relative:
            return False
        if relative[0] == 'six':
            relative = ('six',)
            parts = parts[:self.base_length] + relative
        try:
            info = ModuleInfo(relative[-1], [os.path.join(p, *relative[:-1]) for p in self.mu_paths])
        except ImportError:
            return False
        if not info.pkg_dir and not info.py_src:
            raise AnsibleError('Could not find python source for imported module support code for %s' % '.'.join(parts))
        self.name_parts = parts
        self.is_package = bool(info.pkg_dir) and relative != ('basic',)
        self.path = info.path
        self.source = info.get_source()
        self.py_src = True
        return True


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    base_length = 5
    redirect_first = True

